  from jsonb_to_recordset($j$[{"topic":"math","band":"c9-10","difficulty":1,"q":"a = ৩, b = ৪ হলে (a + b)² এর মান কত?","options":["৩৭","৪৯","২৫","১৪"],"answer_idx":1,"explanation":"(a + b)² = (৩ + ৪)² = ৭² = ৪৯।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c9-10","difficulty":1,"q":"৮² − ৬² এর মান কত?","options":["২৮","১০০","১২৪","৪"],"answer_idx":0,"explanation":"a² − b² = (a + b)(a − b) = ১৪ × ২ = ২৮।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c9-10","difficulty":2,"q":"x² + ৩x − ৪ = ০ সমীকরণের মূল দুটির যোগফল কত?","options":["৩","৫","−৩","−৪"],"answer_idx":2,"explanation":"x² + bx + c = ০ এর মূলদ্বয়ের যোগফল −b। এখানে −(৩) = −৩।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c9-10","difficulty":2,"q":"৭, ১৩, ১৯, … ধারার ২০তম পদ কত?","options":["১২০","১১৫","১২৭","১২১"],"answer_idx":3,"explanation":"সাধারণ অন্তর = ৬। n-তম পদ = a + (n−১)d = ৭ + ১৯ × ৬ = ১২১।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c9-10","difficulty":3,"q":"৩, ৬, ৯, … ধারার প্রথম ১১টি পদের যোগফল কত?","options":["৩৬৩","১৯৮","১৮৭","২০৯"],"answer_idx":1,"explanation":"যোগফল = n/২ × {২a + (n−১)d} = ১১/২ × {৬ + ৩০} = ১৯৮।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c9-10","difficulty":1,"q":"একটা সমকোণী ত্রিভুজের দুই বাহু ৪০ ও ৪২ সেমি। অতিভুজ কত সেমি?","options":["৮২","৫৮","৫৯","৫৭"],"answer_idx":1,"explanation":"অতিভুজ² = ৪০² + ৪২² = ৩৩৬৪, তাই অতিভুজ = ৫৮ সেমি।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"topic":"math","band":"c9-10","difficulty":2,"q":"একটা সিলিন্ডারের ব্যাসার্ধ ৭ সেমি ও উচ্চতা ৮ সেমি। আয়তন কত ঘনসেমি? (π = ২২/৭)","options":["৩৫২","১২৫৪","১২৩২","১৫৪"],"answer_idx":2,"explanation":"আয়তন = π r² h = (২২/৭) × ৭² × ৮ = ১২৩২ ঘনসেমি।","source":"গণিতের হিসাব; প্রোগ্রামে দুই আলাদা পদ্ধতিতে মিলিয়ে নেওয়া"},{"